module TopModule (
    input  wire clk,
    input  wire resetn,
    input  wire in,
    output wire out
);

    // 4-stage shift register
    reg [3:0] shift_reg;

    always @(posedge clk) begin
        if (!resetn) begin
            shift_reg <= 4'b0000;
        end else begin
            shift_reg <= {shift_reg[2:0], in};
        end
    end

    // Output the last stage of the shift register
    assign out = shift_reg[3];

endmodule
